def changed_paths(before, after):
    """Return sorted dot-separated paths for additions, removals, or unequal leaves.

    Recurses only where both values are dictionaries; treats lists atomically.
    If an entire key is added/removed, only that parent path is returned.
    """
    changes = set()
    _diff(before, after, "", changes)
    return sorted(changes)


def _diff(before, after, prefix, changes):
    for key in before:
        path = f"{prefix}.{key}" if prefix else key
        if key not in after:
            changes.add(path)
        elif isinstance(before[key], dict) and isinstance(after[key], dict):
            _diff(before[key], after[key], path, changes)
        elif before[key] != after[key]:
            changes.add(path)

    for key in after:
        if key not in before:
            path = f"{prefix}.{key}" if prefix else key
            changes.add(path)
```

