from copy import deepcopy


def merge(base, overlay):
    """Recursively merge two dictionaries.

    Overlay values replace base values. Both dicts and None are replaced
    in place (None does not delete a key). Only nested dicts are merged
    recursively; all other values (lists, primitives, None) are taken
    from the overlay when present.

    The returned dict is deeply independent of both inputs.
    """
    result = {}

    for key, base_val in base.items():
        if key in overlay:
            overlay_val = overlay[key]
            if isinstance(base_val, dict) and isinstance(overlay_val, dict):
                result[key] = merge(base_val, overlay_val)
            else:
                result[key] = deepcopy(overlay_val)
        else:
            result[key] = deepcopy(base_val)

    for key, overlay_val in overlay.items():
        if key not in base:
            result[key] = deepcopy(overlay_val)

    return result
```

