def normalize(path: str) -> str:
    """Normalize an absolute POSIX-like path.

    - Rejects non-absolute paths with ValueError.
    - Collapses repeated '/' characters.
    - Ignores '.' components.
    - Resolves '..' without going above root.
    - Returns '/' for root.
    - Never returns a trailing slash (except root itself).
    - Performs no filesystem access.
    """
    if not path.startswith("/"):
        raise ValueError(f"not an absolute path: {path!r}")

    stack: list[str] = []
    for part in path.split("/"):
        if part == "" or part == ".":
            continue
        if part == "..":
            if stack:
                stack.pop()
        else:
            stack.append(part)

    if not stack:
        return "/"
    return "/" + "/".join(stack)
```

