from collections import deque

def admit(times, limit, window):
    if limit < 1:
        raise ValueError("limit must be >= 1")
    if window < 1:
        raise ValueError("window must be >= 1")

    accepted = deque()
    result = []

    for t in times:
        threshold = t - window
        while accepted and accepted[0] <= threshold:
            accepted.popleft()

        if len(accepted) < limit:
            result.append(True)
            accepted.append(t)
        else:
            result.append(False)

    return result
