import heapq


def order(deps):
    nodes = set(deps)
    for prereqs in deps.values():
        nodes.update(prereqs)

    remaining = {node: len(deps.get(node, ())) for node in nodes}

    dependents = {node: [] for node in nodes}
    for node, prereqs in deps.items():
        for p in prereqs:
            dependents[p].append(node)

    heap = [node for node in nodes if remaining[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dep in dependents[node]:
            remaining[dep] -= 1
            if remaining[dep] == 0:
                heapq.heappush(heap, dep)

    if len(result) != len(nodes):
        raise ValueError("cycle detected")

    return result
```

